import {repository} from './storage.js';
import {hideWarehouseJob,removeCandidateKeepRelations,removeCandidatesKeepRelations} from './deletion.js';
import {renderPlanner} from './calendar.js';
import {uid,dateString,dayOffset,reviewKeys,reviewLabels,measures,defaultMetrics,countMeasure,percentage,matchingCandidates,newCandidate,moveCandidate,createSeed} from './model.js';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{const p={trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',people:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12a22 22 0 0 0 18 0M12 12v4"/>',chart:'<path d="M4 3v18h18M9 16v-5M14 16V7M19 16v-9"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h5"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',link:'<path d="m10 13 4-4M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',grid:'<rect x="3" y="3" width="7" height="18" rx="1"/><rect x="14" y="3" width="7" height="18" rx="1"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.file}</svg>`;};
const btn=(text,action,primary=false,extra='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${text}</button>`;
const opts=(items,value='',empty='')=>(empty?`<option value="">${esc(empty)}</option>`:'')+items.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('');
const field=(label,name,value='',type='text',required=false,full=false)=>`<div class="field ${full?'full':''}"><label for="f-${name}">${esc(label)}${required?' *':''}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></div>`;
const selectField=(label,name,items,value='',empty='',full=false)=>`<div class="field ${full?'full':''}"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${opts(items,value,empty)}</select></div>`;
const noteField=(name,value='',label='备注')=>`<div class="field full"><label for="f-${name}">${esc(label)}</label><textarea id="f-${name}" name="${name}" rows="3">${esc(value)}</textarea></div>`;
const nav=[['ledger','招聘台账','people'],['calendar','日历待办','calendar'],['jobs','岗位仓库','briefcase'],['analytics','招聘分析','chart'],['documents','工作文档','file'],['resources','HR资源','folder']];
let state,page='ledger',view='table',calView='month',calDate=new Date(),q='',jobFilter='',ownerFilter='',stageFilter='',start='',end='',assetKind='',jobStatus='',currentCandidate=null,importData=null,stageDraft=null;
let toastTimer,ledgerPage=1,showCompleted=false;
const selectedCandidates=new Set();
const toneNames=['sky','butter','lavender','olive','rose','canyon','teal'];
const stageTone=id=>({screen:'butter',schedule:'canyon',first:'sky',second:'lavender',third:'rose',offer:'olive',join:'teal',hired:'teal',rejected:'muted'}[id]||toneNames[Math.max(0,state.stages.findIndex(s=>s.id===id))%toneNames.length]);
const jobTone=id=>toneNames[Math.max(0,state.jobs.findIndex(j=>j.id===id))%toneNames.length];
const pageSize=12;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
const jobName=id=>state.jobs.find(j=>j.id===id)?.name||'未分配岗位';
const stageName=id=>state.stages.find(s=>s.id===id)?.name||'已移除阶段';
const owners=()=>[...new Set(['林晓','陈默',...state.jobs.map(j=>j.owner),...state.candidates.map(c=>c.owner)])].filter(Boolean);
const stageOptions=()=>state.stages.map(s=>[s.id,s.name]);
const jobOptions=()=>state.jobs.map(j=>[j.id,j.name]);
const filtered=()=>state.candidates.filter(c=>(!q||[c.name,c.phone,c.email,c.tags,jobName(c.jobId)].join(' ').toLowerCase().includes(q.toLowerCase()))&&(!jobFilter||c.jobId===jobFilter)&&(!ownerFilter||c.owner===ownerFilter)&&(!stageFilter||c.stageId===stageFilter)&&(!start||c.appliedAt>=start)&&(!end||c.appliedAt<=end));
async function commit(fn){const next=structuredClone(state);fn(next);try{await repository.save(next);state=next;render();return true;}catch(e){toast('保存失败：浏览器存储空间不足或不可用。请备份后重试。');return false;}}
function modal(title,body,submitText='保存',handler=null){const d=$('#modal');d.innerHTML=`<form id="modal-form"><div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}<div id="form-error" class="error" role="alert"></div></div><div class="modal-footer"><button type="button" class="btn" data-action="close-modal">取消</button>${handler?`<button type="submit" class="btn primary">${esc(submitText)}</button>`:''}</div></form>`;if(!d.open)d.showModal();$('#modal-form').onsubmit=async e=>{e.preventDefault();$('#form-error').textContent='';const b=$('button[type=submit]',d);if(b)b.disabled=true;try{await handler?.(Object.fromEntries(new FormData(e.target)),e.target);}catch(err){$('#form-error').textContent=err.message||'操作失败，请重试。';}finally{if(b)b.disabled=false;}};}
const closeModal=()=>$('#modal').close();
function showError(s){$('#form-error').textContent=s;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}"><div class="empty">没有符合条件的记录，请调整筛选或新建。</div></td></tr>`}</tbody></table></div>`;}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="row">${actions}</div></div>`;}
function filterBar(analysis=false){return `<div class="filters ${analysis?'analysis-filters':''}">${analysis?'':`<div class="search">${icon('search')}<input id="search" aria-label="搜索候选人" placeholder="搜索姓名、电话、岗位或标签" value="${esc(q)}"></div>`}<select data-filter="jobFilter" aria-label="筛选岗位">${opts(jobOptions(),jobFilter,'全部岗位')}</select><select data-filter="ownerFilter" aria-label="筛选招聘负责人">${opts(owners(),ownerFilter,'全部负责人')}</select>${analysis?'':`<select data-filter="stageFilter" aria-label="筛选阶段">${opts(stageOptions(),stageFilter,'全部阶段')}</select>`}<label class="row"><small>${analysis?'建档日期':'建档'}</small><input type="date" aria-label="开始日期" data-filter="start" value="${start}"><small>至</small><input type="date" aria-label="结束日期" data-filter="end" value="${end}"></label>${btn('重置','reset-filters')}</div>`;}
function render(){const title=nav.find(n=>n[0]===page)?.[1];document.title=`${title} · 人贩子系统`;$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="logo">${icon('people')}</div><div><strong>人贩子系统</strong><small>让招聘有条不紊</small></div></div><div class="nav-label">招聘管理</div><nav class="nav" aria-label="主导航">${nav.map(([id,name,i])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${name}</span>${id==='ledger'?`<span class="count">${state.candidates.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-note"><b>◦ 本地工作空间</b>数据和文件保存在当前浏览器。${btn('备份数据','backup',false,'style="margin-top:10px;font-size:11px;padding:5px 9px;min-height:28px"')}</div><div class="profile"><span class="avatar">HR</span><div>招聘负责人<small style="display:block">个人工作空间</small></div></div></div></aside><div><header class="topbar"><div class="row"><button class="icon-btn mobile-menu" data-action="menu" aria-label="打开导航">${icon('menu')}</button><span>招聘管理</span><span>/</span><span style="color:var(--ink)">${title}</span></div><div class="row"><span class="date-label">${new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})}</span><span class="pill neutral">示例数据 · 可编辑</span></div></header><main class="main page-enter" data-current-page="${page}">${({ledger:renderLedger,calendar:renderCalendar,jobs:renderJobs,analytics:renderAnalytics,documents:renderAssets,resources:renderAssets})[page]()}</main></div></div>`;bindPage();}
function renderLedger(){const rows=filtered();const eligible=new Set(rows.map(c=>c.id));for(const id of selectedCandidates)if(!eligible.has(id))selectedCandidates.delete(id);ledgerPage=Math.min(ledgerPage,Math.max(1,Math.ceil(rows.length/pageSize)));const active=state.candidates.filter(c=>state.stages.find(s=>s.id===c.stageId)?.kind==='active').length;const interviews=state.events.filter(e=>e.date===dateString()&&!e.done&&e.type==='面试').length;return heading('招聘台账','从第一份简历，到下一位新同事。',btn(icon('settings')+'流程设置','stages')+btn(icon('plus')+'新建候选人','new-candidate',true))+`<div class="summary"><div><label>全部候选人</label><strong>${state.candidates.length}</strong><small>持续积累每一份人才连接</small></div><div><label>正在招聘流程中</label><strong>${active}</strong><small>从筛选到待入职</small></div><div><label>今日面试</label><strong>${interviews}</strong><small>日历中尚未完成的安排</small></div><div><label>已入职</label><strong>${countMeasure(state.candidates,'hired')}</strong><small>已记录入职日期的候选人</small></div></div><section class="panel"><div class="toolbar"><div class="row"><h2>候选人</h2><span class="tag">${rows.length} 人</span></div><div class="row wrap"><div class="segmented" aria-label="台账视图"><button data-view="table" class="${view==='table'?'active':''}">${icon('list')} 表格</button><button data-view="board" class="${view==='board'?'active':''}">${icon('grid')} 看板</button></div>${btn(icon('upload')+'导入','import')}${btn(icon('download')+'导出','export')}</div></div>${filterBar()}${view==='table'?renderBulkActions(rows):''}${view==='table'?table(['<label class="select-page-label"><input id="select-page" type="checkbox" data-select-page aria-label="全选本页"><span>全选本页</span></label>','候选人','应聘岗位','当前阶段','来源','招聘负责人','建档日期','操作'],rows.slice((ledgerPage-1)*pageSize,ledgerPage*pageSize).map(c=>`<tr class="${selectedCandidates.has(c.id)?'candidate-selected':''}"><td class="candidate-check-cell"><input type="checkbox" data-select-candidate="${c.id}" aria-label="选择候选人：${esc(c.name)}" ${selectedCandidates.has(c.id)?'checked':''}></td><td><div class="candidate-cell"><span class="avatar">${esc(c.name.slice(0,1))}</span><div><button class="name" data-candidate="${c.id}">${esc(c.name)}</button><small>${esc(c.experience?c.experience+'年经验':'经验待补充')} · ${esc(c.education||'学历待补充')}</small></div></div></td><td>${esc(jobName(c.jobId))}</td><td><select class="stage-select" data-tone="${stageTone(c.stageId)}" data-move="${c.id}" aria-label="${esc(c.name)}的当前阶段">${opts(stageOptions(),c.stageId)}</select></td><td>${esc(c.source)}</td><td>${esc(c.owner)}</td><td>${esc(c.appliedAt)}</td><td><div class="row candidate-actions"><button class="inline-link" data-candidate="${c.id}">查看详情</button><button class="icon-btn delete-icon" data-delete-candidate="${c.id}" aria-label="删除候选人：${esc(c.name)}" title="删除候选人">${icon('trash')}</button></div></td></tr>`)):`<div class="kanban">${state.stages.map(s=>`<section class="lane" data-tone="${stageTone(s.id)}" data-stage="${s.id}"><div class="lane-head">${esc(s.name)}<span>${rows.filter(c=>c.stageId===s.id).length}</span></div>${rows.filter(c=>c.stageId===s.id).map(c=>`<article class="kanban-card" draggable="true" data-drag="${c.id}"><div class="row between"><button data-candidate="${c.id}">${esc(c.name)}</button><div class="row"><span class="avatar">${esc(c.name.slice(0,1))}</span><button class="icon-btn delete-icon" draggable="false" data-delete-candidate="${c.id}" aria-label="删除候选人：${esc(c.name)}" title="删除候选人">${icon('trash')}</button></div></div><p>${esc(jobName(c.jobId))}</p><div class="row between"><span class="tag">${esc(c.source)}</span><small>${esc(c.owner)}</small></div></article>`).join('')}</section>`).join('')}</div>`}<div class="table-foot"><span>共 ${rows.length} 位候选人</span><span class="row">${view==='table'?`${btn('上一页','ledger-prev',false,ledgerPage===1?'disabled':'')}<span>${ledgerPage} / ${Math.max(1,Math.ceil(rows.length/pageSize))}</span>${btn('下一页','ledger-next',false,ledgerPage*pageSize>=rows.length?'disabled':'')}`:'更改自动保存在此浏览器'}</span></div></section><p class="footer-note">流程可按公司需要调整 · 点击姓名查看完整资料与流转记录</p>`;}
function renderBulkActions(rows){
 const selected=selectedCandidates.size,all=rows.length>0&&rows.every(c=>selectedCandidates.has(c.id));
 return `<div class="bulk-actions"><div><p class="bulk-selection-count" role="status" aria-live="polite">已选择 <strong>${selected}</strong> 位候选人</p><small>翻页保留选择 · 更改搜索或筛选会清空选择</small></div><div class="row wrap">${btn(all?'已全选筛选结果（'+rows.length+'人）':'选择全部筛选结果（'+rows.length+'人）','select-filtered',false,all||!rows.length?'disabled':'')}${btn('清空选择','clear-selection',false,selected?'':'disabled')}<button class="btn danger bulk-delete" data-action="bulk-delete" ${selected?'':'disabled'}>${icon('trash')}批量删除${selected?'（'+selected+'）':''}</button></div></div>`;
}
function deleteSelectedCandidates(){
 const ids=[...selectedCandidates];const candidates=state.candidates.filter(c=>selectedCandidates.has(c.id));
 if(!ids.length){toast('请先勾选候选人');return;}
 if(candidates.length!==ids.length){toast('所选候选人已变化，请重新选择');render();return;}
 const targets=new Set(ids),events=state.events.filter(e=>targets.has(e.candidateId)).length,files=state.assets.filter(a=>targets.has(a.candidateId)).length;
 const names=candidates.slice(0,8).map(c=>c.name).join('、')+(candidates.length>8?'等':'');
 confirmDelete('批量删除候选人',`确认删除已选择的 ${ids.length} 位候选人（${names}）？候选人资料、评估和流转记录将删除。关联的 ${events} 条日程及 ${files} 份附件全部保留，只解除候选人关联；简历附件保留在工作文档中。此操作会更新招聘统计。`,async()=>{
  const success=await commit(s=>removeCandidatesKeepRelations(s,ids));
  if(success){selectedCandidates.clear();if(targets.has(currentCandidate)){$('#drawer').close();currentCandidate=null;}render();}
  return success;
 });
}
function renderJobs(){const jobs=state.jobs.filter(j=>!j.warehouseHiddenAt&&(!q||[j.name,j.department,j.owner].join(' ').includes(q))&&(!jobStatus||j.status===jobStatus));return heading('岗位仓库','把每个招聘需求，整理得清清楚楚。',btn(icon('plus')+'新建岗位','new-job',true))+`<div class="panel toolbar"><div class="search">${icon('search')}<input id="search" aria-label="搜索岗位" placeholder="搜索岗位、部门或负责人" value="${esc(q)}"></div><select id="job-status" aria-label="岗位状态">${opts(['招聘中','暂停','已关闭'],jobStatus,'全部状态')}</select></div><div class="grid">${jobs.map(j=>{const hired=state.candidates.filter(c=>c.jobId===j.id&&c.hiredAt).length;return `<article class="panel job-card" data-tone="${jobTone(j.id)}"><div><div class="row between"><small>${esc(j.department)}</small><div class="row"><span class="pill ${j.status==='招聘中'?'':'neutral'}">${esc(j.status)}</span><button class="icon-btn delete-icon" data-delete-job="${j.id}" aria-label="删除岗位：${esc(j.name)}" title="从岗位仓库删除">${icon('trash')}</button></div></div><h2>${esc(j.name)}</h2><small>${esc(j.city)} · ${esc(j.level)} · ${esc(j.salary)}</small></div><div><div class="row between"><small>招聘进度</small><span>${hired} <small>/ ${j.headcount} 人</small></span></div><div class="progress"><span style="width:${Math.min(100,hired/Math.max(j.headcount,1)*100)}%"></span></div></div><div class="detail-grid"><div><small>招聘负责人</small>${esc(j.owner)}</div><div><small>截止日期</small>${esc(j.deadline||'未设置')}</div></div><div class="row between"><small>发布于 ${esc(j.publishedAt)}</small><button class="inline-link" data-edit-job="${j.id}">编辑岗位 ${icon('arrow')}</button></div></article>`;}).join('')||'<div class="empty">暂无岗位，点击“新建岗位”开始。</div>'}</div>`;}
function renderCalendar(){return renderPlanner(state,{calDate,calView,assetKind,showCompleted},{esc,icon,btn,opts,dateString,heading});}
function renderAnalytics(){const rows=filtered();return heading('招聘分析','先看整体转化，再找到值得改进的环节。',btn(icon('plus')+'自定义指标','new-metric',true))+`<div class="panel">${filterBar(true)}</div><section class="panel"><div class="panel-head row between"><h2>核心指标</h2><small>当前筛选范围 · ${rows.length} 位候选人</small></div><div class="kpis">${state.metrics.filter(m=>!m.custom).map(m=>metricCard(m,rows)).join('')}</div><div class="custom-kpis">${state.metrics.filter(m=>m.custom).map(m=>`<div class="custom-kpi"><div class="row between"><label>${esc(m.name)}</label><button class="icon-btn" data-edit-metric="${m.id}" aria-label="编辑${esc(m.name)}">${icon('settings')}</button></div><strong>${percentage(countMeasure(rows,m.numerator),countMeasure(rows,m.denominator))}</strong><small>${esc(measures[m.numerator])} / ${esc(measures[m.denominator])}</small><small>${countMeasure(rows,m.numerator)} / ${countMeasure(rows,m.denominator)}</small></div>`).join('')}<button class="btn" data-action="new-metric">${icon('plus')} 添加自定义比率</button></div></section><section class="panel"><div class="panel-head row between"><h2>招聘漏斗</h2><small>阶段实际到达人数 · 同一候选人每阶段计一次</small></div><div class="funnel">${state.stages.filter(s=>s.kind!=='rejected').map((s,i,arr)=>{const count=rows.filter(c=>c.stageId===s.id||c.history.some(h=>h.to===s.id)).length;const prev=i?rows.filter(c=>c.stageId===arr[i-1].id||c.history.some(h=>h.to===arr[i-1].id)).length:0;return `<div class="funnel-row"><span>${esc(s.name)}</span><div class="funnel-track"><span style="width:${rows.length?count/rows.length*100:0}%;opacity:${1-i*.065}"></span></div><b>${count}</b><small>${i?'较上阶段 '+percentage(count,prev):'建档人群'}</small></div>`;}).join('')}</div></section><section class="panel"><div class="panel-head row between"><h2>岗位对比</h2><small>评估结果与入职记录实时计算</small></div>${table(['岗位','简历数',...defaultMetrics.slice(0,4).map(m=>m.name),'入职人数'],state.jobs.filter(j=>!jobFilter||j.id===jobFilter).map(j=>{const r=rows.filter(c=>c.jobId===j.id);return `<tr><td>${esc(j.name)}</td><td>${r.length}</td>${defaultMetrics.slice(0,4).map(m=>`<td>${percentage(countMeasure(r,m.numerator),countMeasure(r,m.denominator))}</td>`).join('')}<td>${countMeasure(r,'hired')}</td></tr>`;}))}</section><p class="footer-note">时间范围按首次建档日期筛选。比率根据详情中录入的评估结果计算；跳阶段不自动记为通过。分母为 0 显示“—”。漏斗允许跳阶段，因此相邻阶段比例可能超过 100%。</p>`;}
function metricCard(m,rows){const a=countMeasure(rows,m.numerator),b=countMeasure(rows,m.denominator);return `<div class="kpi" title="${esc(measures[m.numerator])} ÷ ${esc(measures[m.denominator])}"><label>${esc(m.name)}</label><strong>${percentage(a,b)}</strong><small>${a} / ${b}</small></div>`;}
function renderAssets(){const kind=page==='documents'?'document':'resource';const rows=state.assets.filter(a=>a.kind===kind&&(!q||[a.name,a.category,a.url].join(' ').toLowerCase().includes(q.toLowerCase()))&&(!assetKind||a.category===assetKind));const categories=[...new Set(state.assets.filter(a=>a.kind===kind).map(a=>a.category))];return heading(page==='documents'?'工作文档':'HR资源',page==='documents'?'把常用文档放在一起，需要时随手找到。':'招聘模板、实用工具与好用的网页链接。',(page==='resources'?btn(icon('link')+'添加网页链接','new-link'):'')+btn(icon('upload')+'上传文件','upload-assets',true))+`<div class="panel toolbar"><div class="search">${icon('search')}<input id="search" aria-label="搜索文件或资源" placeholder="搜索名称、分类或链接" value="${esc(q)}"></div><select id="asset-category" aria-label="资源分类">${opts(categories,assetKind,'全部分类')}</select></div>${rows.length?`<div class="grid">${rows.map(a=>`<article class="panel asset-card"><div class="row between"><span class="asset-icon">${a.url?icon('link'):esc(a.name.split('.').pop().toUpperCase().slice(0,5))}</span><span class="tag">${esc(a.category||'未分类')}</span></div><div><h3>${esc(a.name)}</h3><small>${a.url?esc(new URL(a.url).hostname):formatSize(a.size)} · ${esc(a.createdAt.slice(0,10))}</small></div><div class="row between">${a.url?`<a class="btn" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">打开网页 ${icon('arrow')}</a>`:`<button class="btn" data-download-asset="${a.id}">${icon('download')} 下载文件</button>`}<div class="row"><button class="icon-btn" data-edit-asset="${a.id}" aria-label="编辑${esc(a.name)}">${icon('settings')}</button><button class="icon-btn danger-text" data-delete-asset="${a.id}" aria-label="删除${esc(a.name)}">${icon('close')}</button></div></div></article>`).join('')}</div>`:`<div class="upload-zone">${icon('folder')}<h2 style="margin-top:12px">${q||assetKind?'没有匹配的内容':'你的资料库，从第一份文件开始'}</h2><p>支持 Word、PDF、Excel 等文件，上传后可在当前浏览器下载使用。</p>${btn(icon('upload')+'选择文件','upload-assets')}</div>`}<p class="footer-note">文件仅存储在当前浏览器。Word 等文件下载后打开；网页链接在新标签页访问。</p>`;}
const formatSize=n=>n>1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
function bindPage(){const pageSelection=$('#select-page');if(pageSelection){const rows=filtered().slice((ledgerPage-1)*pageSize,ledgerPage*pageSize);pageSelection.checked=rows.length>0&&rows.every(c=>selectedCandidates.has(c.id));pageSelection.indeterminate=rows.some(c=>selectedCandidates.has(c.id))&&!pageSelection.checked;pageSelection.disabled=!rows.length;}$('#show-completed')?.addEventListener('change',e=>{showCompleted=e.target.checked;render();});const search=$('#search');if(search)search.oninput=()=>{q=search.value;selectedCandidates.clear();ledgerPage=1;const pos=search.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos);};$$('[data-filter]').forEach(el=>el.onchange=()=>{selectedCandidates.clear();ledgerPage=1;({jobFilter:v=>jobFilter=v,ownerFilter:v=>ownerFilter=v,stageFilter:v=>stageFilter=v,start:v=>start=v,end:v=>end=v})[el.dataset.filter](el.value);if(start&&end&&start>end){toast('开始日期不能晚于结束日期');start='';end='';}render();});$('#job-status')?.addEventListener('change',e=>{jobStatus=e.target.value;render();});for(const id of ['asset-category','event-type-filter'])$('#'+id)?.addEventListener('change',e=>{assetKind=e.target.value;render();});$$('[data-drag]').forEach(el=>el.ondragstart=e=>{if(e.target.closest('[data-delete-candidate]')){e.preventDefault();return;}e.dataTransfer.setData('text/plain',el.dataset.drag);});$$('.lane').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('drag-over');};el.ondragleave=()=>el.classList.remove('drag-over');el.ondrop=async e=>{e.preventDefault();el.classList.remove('drag-over');await move(e.dataTransfer.getData('text/plain'),el.dataset.stage);};});}
async function move(id,stageId){if(!state.candidates.some(c=>c.id===id)||!state.stages.some(s=>s.id===stageId))return;if(await commit(s=>moveCandidate(s.candidates.find(c=>c.id===id),stageId,s.stages))){toast('已更新阶段，流转记录已保留');if($('#drawer').open)showCandidate(id);}}
function showCandidate(id){const c=state.candidates.find(c=>c.id===id);if(!c)return;currentCandidate=id;const d=$('#drawer');d.innerHTML=`<div class="modal-head"><span class="muted">候选人详情</span><button class="icon-btn" data-action="close-drawer" aria-label="关闭详情">${icon('close')}</button></div><div class="drawer-header"><div class="row"><span class="avatar">${esc(c.name.slice(0,1))}</span><div><h2 id="drawer-title">${esc(c.name)}</h2><small>${esc(jobName(c.jobId))} · ${esc(c.city||'城市未填写')}</small></div><div class="row candidate-detail-actions"><button class="btn" data-edit-candidate="${id}">编辑资料</button><button class="btn danger" data-delete-candidate="${id}">${icon('trash')}删除候选人</button></div></div><div class="row" style="margin-top:20px"><label for="drawer-stage">当前阶段</label><select id="drawer-stage" class="stage-select" data-tone="${stageTone(c.stageId)}" data-move="${id}">${opts(stageOptions(),c.stageId)}</select><span class="tag">${esc(c.tags||'暂无标签')}</span></div></div><div class="modal-body"><div class="detail-grid">${[['联系电话',c.phone],['邮箱',c.email],['工作年限',c.experience?c.experience+' 年':''],['学历',c.education],['期望薪资',c.salary],['候选人来源',c.source],['招聘负责人',c.owner],['首次建档日期',c.appliedAt]].map(([l,v])=>`<div><small>${l}</small>${esc(v||'未填写')}</div>`).join('')}</div><section class="drawer-section"><div class="row between"><h3>评估与录用结果</h3><button class="inline-link" data-edit-results="${id}">录入结果</button></div><div class="detail-grid">${reviewKeys.map(k=>`<div><small>${reviewLabels[k]}</small>${esc(({pending:'待评估',pass:'通过',fail:'未通过',sent:'已发出，待回复',accepted:'已接受',rejected:'已拒绝'})[c.reviews[k]])}</div>`).join('')}<div><small>实际入职日期</small>${esc(c.hiredAt||'尚未入职')}</div></div></section><section class="drawer-section"><div class="row between"><h3>面试与跟进安排</h3><button class="inline-link" data-schedule-candidate="${id}">添加安排</button></div>${state.events.filter(e=>e.candidateId===id).map(e=>`<button class="event-row" data-event="${e.id}"><div>${e.done?'✓ ':''}${esc(e.title)}<small>${esc(e.date)} ${esc(e.time)} · ${esc(e.type)}</small></div></button>`).join('')||'<small>暂无日程安排</small>'}</section><section class="drawer-section"><div class="row between"><h3>简历与附件</h3><button class="inline-link" data-candidate-upload="${id}">上传附件</button></div>${state.assets.filter(a=>a.candidateId===id).map(a=>`<div class="row between" style="margin:10px 0"><button class="inline-link" data-download-asset="${a.id}">${esc(a.name)}</button><button class="danger-text" data-delete-asset="${a.id}">删除</button></div>`).join('')||'<small>暂无附件，支持 PDF、Word 等文件</small>'}</section><section class="drawer-section"><h3>沟通备注</h3><p style="white-space:pre-wrap;font-size:13px">${esc(c.notes||'暂无备注')}</p></section><section class="drawer-section"><h3>流转记录</h3><div class="timeline">${[...c.history].reverse().map(h=>`<div class="timeline-item">${esc(h.label||stageName(h.to))}<small>${esc(h.at.replace('T',' ').slice(0,16))} · ${esc(h.note)}</small></div>`).join('')||'<small>暂无流转记录</small>'}</div></section></div>`;if(!d.open)d.showModal();}
function candidateForm(id){const c=state.candidates.find(c=>c.id===id)||newCandidate({jobId:state.jobs[0]?.id||'',stageId:state.stages[0].id});modal(id?'编辑候选人':'新建候选人',`<div class="form-grid">${field('姓名','name',c.name,'text',true)}${selectField('应聘岗位','jobId',jobOptions(),c.jobId,'未分配岗位')}${field('手机号','phone',c.phone,'tel')}${field('邮箱','email',c.email,'email')}${selectField('招聘负责人','owner',owners(),c.owner)}${selectField('来源','source',['主动投递','招聘平台','内推','猎头','其他'],c.source)}${field('所在城市','city',c.city)}${field('工作年限','experience',c.experience,'number')}${selectField('学历','education',['专科及以下','本科','硕士','博士','其他'],c.education,'未填写')}${field('期望薪资','salary',c.salary)}${field('首次建档日期','appliedAt',c.appliedAt,'date',true)}${field('标签','tags',c.tags)}${noteField('notes',c.notes,'沟通备注 / 面试评价')}</div><p class="muted" style="font-size:11px;margin-top:16px">阶段与评估结果在详情中单独修改。相同手机号或邮箱会提示人工处理。</p>`,'保存候选人',async v=>{v.name=v.name.trim();if(!v.name)throw Error('请填写姓名');if(Number(v.experience)<0)throw Error('工作年限不能为负数');const dup=matchingCandidates(state.candidates.filter(r=>r.id!==id),v);if(dup.length&&!$('#allow-duplicate')?.checked){showError('发现相同手机号或邮箱的候选人：'+dup.map(r=>r.name).join('、'));if(!$('#allow-duplicate'))$('#form-error').insertAdjacentHTML('afterend','<label class="checkline" style="margin-top:8px"><input id="allow-duplicate" type="checkbox">我已核对，仍作为独立记录保存</label>');return;}if(await commit(s=>{if(id)Object.assign(s.candidates.find(r=>r.id===id),v,{updatedAt:new Date().toISOString()});else{const n=newCandidate(v);n.stageId=s.stages[0].id;n.history=[{id:uid(),from:null,to:n.stageId,at:new Date().toISOString(),note:'新建候选人'}];s.candidates.unshift(n);}})){closeModal();toast('候选人已保存');if(id&&$('#drawer').open)showCandidate(id);}});}
function resultForm(id){const c=state.candidates.find(c=>c.id===id);modal('录入评估与录用结果',`<div class="hint">各项结果独立记录。切换阶段或跳过面试不会自动记为通过。入职日期用于计算入职人数。</div><div class="form-grid">${reviewKeys.map(k=>selectField(reviewLabels[k],k,k==='offer'?[['pending','尚未发出'],['sent','已发出，待回复'],['accepted','已接受'],['rejected','已拒绝']]:[['pending','待评估'],['pass','通过'],['fail','未通过']],c.reviews[k])).join('')}${field('实际入职日期','hiredAt',c.hiredAt||'','date')}</div>`,'保存结果',async v=>{if(await commit(s=>{const r=s.candidates.find(x=>x.id===id);reviewKeys.forEach(k=>r.reviews[k]=v[k]);r.hiredAt=v.hiredAt||null;r.updatedAt=new Date().toISOString();r.history.push({id:uid(),from:r.stageId,to:r.stageId,at:new Date().toISOString(),note:'更新评估与录用结果'});})){closeModal();showCandidate(id);toast('结果已保存，分析同步更新');}});}
