 modal(id?'编辑日程':bucket==='short'?'新建短期待办':bucket==='long'?'新建长期待办':'新建日程',
 '<div class="form-grid">'+field('日程标题','title',e.title,'text',true,true)+selectField('归属区域','bucket',[['schedule','日历安排'],['short','短期待办'],['long','长期待办']],e.bucket||'schedule')+selectField('类型','type',['面试','Offer','入职','跟进','待办'],e.type)+selectField('关联候选人','candidateId',state.candidates.map(c=>[c.id,c.name+' · '+jobName(c.jobId)]),e.candidateId,'不关联候选人')+field('日期 / 截止日期','date',e.date,'date')+field('时间','time',e.time,'time')+noteField('notes',e.notes)+'<label class="checkline"><input name="done" type="checkbox" '+(e.done?'checked':'')+'>标记为已完成</label>'+(id?'<button type="button" class="btn danger" data-delete-event="'+id+'">删除日程</button>':'')+'</div><p class="muted" style="font-size:12px;margin-top:16px">短期与长期由你手动分类；待办可以不设置截止日期。</p>',
 '保存日程',async v=>{if(!v.title.trim())throw Error('请填写日程标题');if(v.bucket==='schedule'&&!v.date)throw Error('日历安排需要填写日期');v.title=v.title.trim();v.done=v.done==='on';if(await commit(s=>{if(id)Object.assign(s.events.find(x=>x.id===id),v);else s.events.push({id:uid(),...v});})){closeModal();toast('日程已保存');if($('#drawer').open)showCandidate(currentCandidate);}});
